'use client';

import { FC, useState, useRef, useEffect } from 'react';
import { Send, Upload, FileText, X, Bot, User, Calendar, Clock, Users, Check, X as XIcon } from 'lucide-react';

interface Message {
  id: string;
  content: string;
  role: 'user' | 'assistant';
  timestamp: Date;
  type: 'text' | 'meeting_slots' | 'confirmation';
  meetingSlots?: {
    id: string;
    date: string;
    time: string;
    duration: string;
    availableAttendees: string[];
  }[];
  selectedSlot?: {
    id: string;
    date: string;
    time: string;
    duration: string;
    attendees: string[];
  };
}

const ChatPage: FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      content: 'Hello! I can help you with various tasks like scheduling meetings, organizing documents, and answering questions about your organization. How can I assist you today?',
      role: 'assistant',
      timestamp: new Date(),
      type: 'text',
    },
  ]);
  const [input, setInput] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    // Add user message
    const userMessage: Message = {
      id: Date.now().toString(),
      content: input,
      role: 'user',
      timestamp: new Date(),
      type: 'text',
    };
    setMessages((prev) => [...prev, userMessage]);
    setInput('');

    // Simulate AI processing
    setTimeout(() => {
      if (input.toLowerCase().includes('schedule') && input.toLowerCase().includes('meeting')) {
        // Simulate meeting scheduling response
        const aiMessage: Message = {
          id: (Date.now() + 1).toString(),
          content: "I'll help you schedule a meeting. I've analyzed the team's calendars and found the following available time slots for all team members:",
          role: 'assistant',
          timestamp: new Date(),
          type: 'meeting_slots',
          meetingSlots: [
            {
              id: '1',
              date: '2024-03-25',
              time: '10:00 AM',
              duration: '1 hour',
              availableAttendees: ['John Smith', 'Sarah Johnson', 'Mike Chen', 'Emma Davis'],
            },
            {
              id: '2',
              date: '2024-03-25',
              time: '2:00 PM',
              duration: '1 hour',
              availableAttendees: ['John Smith', 'Sarah Johnson', 'Mike Chen', 'Emma Davis'],
            },
            {
              id: '3',
              date: '2024-03-26',
              time: '11:00 AM',
              duration: '1 hour',
              availableAttendees: ['John Smith', 'Sarah Johnson', 'Mike Chen', 'Emma Davis'],
            },
          ],
        };
        setMessages((prev) => [...prev, aiMessage]);
      } else {
        // Default response for other queries
        const aiMessage: Message = {
          id: (Date.now() + 1).toString(),
          content: "I understand you're asking about something. Let me help you with that. Could you please provide more details about what you'd like to know?",
          role: 'assistant',
          timestamp: new Date(),
          type: 'text',
        };
        setMessages((prev) => [...prev, aiMessage]);
      }
    }, 1000);
  };

  const handleSlotSelection = (slotId: string) => {
    const selectedSlot = messages
      .find(m => m.type === 'meeting_slots')
      ?.meetingSlots?.find(s => s.id === slotId);

    if (selectedSlot) {
      const confirmationMessage: Message = {
        id: Date.now().toString(),
        content: `I've scheduled the meeting for ${selectedSlot.date} at ${selectedSlot.time} (${selectedSlot.duration}). I'll send calendar invites to all attendees.`,
        role: 'assistant',
        timestamp: new Date(),
        type: 'confirmation',
        selectedSlot: {
          ...selectedSlot,
          attendees: selectedSlot.availableAttendees,
        },
      };
      setMessages((prev) => [...prev, confirmationMessage]);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []);
    setUploadedFiles((prev) => [...prev, ...files]);
  };

  const removeFile = (index: number) => {
    setUploadedFiles((prev) => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="h-[calc(100vh-4rem)] flex flex-col">
      {/* Messages Area - Scrollable */}
      <div className="flex-1 overflow-y-auto">
        <div className="p-4 space-y-4">
          {messages.map((message) => (
            <div
              key={message.id}
              className={`flex ${
                message.role === 'user' ? 'justify-end' : 'justify-start'
              }`}
            >
              <div
                className={`max-w-2xl rounded-lg p-4 ${
                  message.role === 'user'
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 text-gray-900'
                }`}
              >
                <div className="flex items-center mb-2">
                  {message.role === 'assistant' ? (
                    <Bot className="h-5 w-5 mr-2" />
                  ) : (
                    <User className="h-5 w-5 mr-2" />
                  )}
                  <span className="font-medium">
                    {message.role === 'assistant' ? 'Assistant' : 'You'}
                  </span>
                </div>
                
                {message.type === 'text' && (
                  <p className="whitespace-pre-wrap">{message.content}</p>
                )}

                {message.type === 'meeting_slots' && (
                  <div className="space-y-4">
                    <p className="whitespace-pre-wrap">{message.content}</p>
                    <div className="space-y-3">
                      {message.meetingSlots?.map((slot) => (
                        <div
                          key={slot.id}
                          className="bg-white rounded-lg p-4 border border-gray-200"
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex items-center space-x-4">
                              <Calendar className="h-5 w-5 text-blue-500" />
                              <div>
                                <p className="font-medium">
                                  {new Date(slot.date).toLocaleDateString()} at {slot.time}
                                </p>
                                <p className="text-sm text-gray-500">
                                  Duration: {slot.duration}
                                </p>
                              </div>
                            </div>
                            <button
                              onClick={() => handleSlotSelection(slot.id)}
                              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                              Select
                            </button>
                          </div>
                          <div className="mt-3 flex items-center text-sm text-gray-500">
                            <Users className="h-4 w-4 mr-1" />
                            <span>
                              {slot.availableAttendees.length} attendees available
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {message.type === 'confirmation' && message.selectedSlot && (
                  <div className="space-y-3">
                    <p className="whitespace-pre-wrap">{message.content}</p>
                    <div className="bg-white rounded-lg p-4 border border-gray-200">
                      <div className="flex items-center space-x-2 text-green-600">
                        <Check className="h-5 w-5" />
                        <span className="font-medium">Meeting Scheduled</span>
                      </div>
                      <div className="mt-3 space-y-2 text-sm">
                        <p className="flex items-center">
                          <Calendar className="h-4 w-4 mr-2 text-gray-500" />
                          {new Date(message.selectedSlot.date).toLocaleDateString()} at {message.selectedSlot.time}
                        </p>
                        <p className="flex items-center">
                          <Clock className="h-4 w-4 mr-2 text-gray-500" />
                          Duration: {message.selectedSlot.duration}
                        </p>
                        <div className="flex items-center">
                          <Users className="h-4 w-4 mr-2 text-gray-500" />
                          <span>Attendees: {message.selectedSlot.attendees.join(', ')}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Fixed Bottom Section */}
      <div className="flex-shrink-0 bg-white border-t border-gray-200">
        {/* Uploaded Files */}
        {uploadedFiles.length > 0 && (
          <div className="px-4 py-2">
            <div className="flex flex-wrap gap-2">
              {uploadedFiles.map((file, index) => (
                <div
                  key={index}
                  className="flex items-center bg-gray-100 rounded-full px-3 py-1 text-sm"
                >
                  <FileText className="h-4 w-4 mr-2" />
                  <span className="truncate max-w-[200px]">{file.name}</span>
                  <button
                    onClick={() => removeFile(index)}
                    className="ml-2 text-gray-500 hover:text-gray-700"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Input Area - Fixed */}
        <div className="p-4">
          <div className="max-w-4xl mx-auto">
            <div className="flex space-x-4">
              <div className="flex-1">
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Type your message... (e.g., 'Schedule a meeting to discuss the Q2 roadmap')"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 placeholder-gray-500"
                />
              </div>
              <div className="flex space-x-2">
                <label className="cursor-pointer">
                  <input
                    type="file"
                    multiple
                    onChange={handleFileUpload}
                    className="hidden"
                  />
                  <div className="p-2 text-gray-500 hover:text-gray-700">
                    <Upload className="h-6 w-6" />
                  </div>
                </label>
                <button
                  onClick={handleSend}
                  className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <Send className="h-6 w-6" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatPage; 